+import { COST_CODES, type CostCode } from "./codes.ts";
+
+export function describeCode(code: string): string {
+  if (!Object.hasOwn(COST_CODES, code)) throw new Error(`unknown cost code: ${JSON.stringify(code)}`);
+  return COST_CODES[code as CostCode];
+}
+
+export function searchCodes(query: string): CostCode[] {
+  const q = query.toLowerCase();
+  return (Object.keys(COST_CODES) as CostCode[]).filter((code) => COST_CODES[code].toLowerCase().includes(q));
+}
