+import type { InvoiceLine } from "./classify.ts";
+
+export function isCreditNote(line: InvoiceLine): boolean {
+  if (line.amount !== undefined && line.amount < 0) return true;
+  if (line.quantity !== undefined && line.quantity < 0) return true;
+  return /^(hyvitys|credit)/i.test(line.description);
+}
