+import type { InvoiceLine } from "./classify.ts";
+
+const COLUMNS = ["description", "supplier", "quantity", "unit", "amount"] as const;
+type Column = (typeof COLUMNS)[number];
+
+function parseNumber(cell: string, column: Column, row: number): number {
+  const normalized = cell.replace(/[\s ]/g, "").replace(",", ".");
+  if (!/^-?\d+(\.\d+)?$/.test(normalized)) {
+    throw new Error(`row ${row}: cannot parse ${column} "${cell}"`);
+  }
+  return Number(normalized);
+}
+
+export function parseInvoiceCsv(text: string): InvoiceLine[] {
+  const rows = text.split(/\r?\n/).map((raw, i) => ({ raw, row: i + 1 })).filter(({ raw }) => raw.trim() !== "");
+  if (rows.length === 0) return [];
+
+  const header = rows[0].raw.split(";").map((h) => h.trim());
+  for (const h of header) {
+    if (!(COLUMNS as readonly string[]).includes(h)) throw new Error(`unknown column "${h}"`);
+  }
+  const columns = header as Column[];
+
+  return rows.slice(1).map(({ raw, row }) => {
+    const cells = raw.split(";").map((c) => c.trim());
+    if (cells.length > columns.length) throw new Error(`row ${row}: ${cells.length} cells, header has ${columns.length}`);
+    const line: Partial<InvoiceLine> = {};
+    columns.forEach((column, i) => {
+      const cell = cells[i] ?? "";
+      if (cell === "") return;
+      if (column === "quantity" || column === "amount") line[column] = parseNumber(cell, column, row);
+      else line[column] = cell;
+    });
+    if (line.description === undefined) throw new Error(`row ${row}: missing description`);
+    return line as InvoiceLine;
+  });
+}
